import { useState, useEffect } from "react";
import { useMutation, useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { isUnauthorizedError } from "@/lib/authUtils";
import type { ProjectWithRoads, InsertLayerProgress } from "@shared/schema";

interface ProgressModalProps {
  project: ProjectWithRoads;
  road: any;
  layerId: string;
  onClose: () => void;
  onSuccess: () => void;
}

export default function ProgressModal({ 
  project, 
  road, 
  layerId, 
  onClose, 
  onSuccess 
}: ProgressModalProps) {
  const { toast } = useToast();
  const [formData, setFormData] = useState({
    startChainage: "",
    endChainage: "",
    carriagewaySide: "both",
    completionDate: new Date().toISOString().split('T')[0],
    qualityStatus: "approved",
    notes: "",
  });

  const layer = road.layers?.find((l: any) => l.id === layerId);

  const mutation = useMutation({
    mutationFn: async (data: InsertLayerProgress) => {
      await apiRequest("POST", `/api/layers/${layerId}/progress`, data);
    },
    onSuccess: () => {
      toast({
        title: "Success",
        description: "Layer progress updated successfully",
      });
      onSuccess();
    },
    onError: (error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Error",
        description: "Failed to update layer progress",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    mutation.mutate({
      startChainage: Number(formData.startChainage),
      endChainage: Number(formData.endChainage),
      carriagewaySide: formData.carriagewaySide,
      completionDate: formData.completionDate,
      qualityStatus: formData.qualityStatus,
      notes: formData.notes,
    });
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }));
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="bg-card rounded-xl shadow-2xl w-full max-w-lg max-h-[90vh] flex flex-col overflow-hidden">
        <div className="flex items-center justify-between p-6 border-b border-border">
          <h3 className="text-xl font-semibold text-card-foreground">Update Layer Progress</h3>
          <button
            onClick={onClose}
            className="text-muted-foreground hover:text-foreground transition-colors"
            data-testid="button-close-modal"
          >
            <i className="fas fa-times text-xl"></i>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto">
          <div className="p-6 space-y-6">
          <div>
            <Label className="block text-sm font-medium text-muted-foreground mb-2">Construction Layer</Label>
            <div className="w-full px-4 py-3 border border-input rounded-lg bg-muted text-card-foreground">
              {layer?.name || "Unknown Layer"}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label className="block text-sm font-medium text-muted-foreground mb-2">Start Chainage (km)</Label>
              <Input
                type="number"
                step="0.01"
                name="startChainage"
                value={formData.startChainage}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
                placeholder="0.00"
                required
                data-testid="input-start-chainage"
              />
            </div>

            <div>
              <Label className="block text-sm font-medium text-muted-foreground mb-2">End Chainage (km)</Label>
              <Input
                type="number"
                step="0.01"
                name="endChainage"
                value={formData.endChainage}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
                placeholder="0.00"
                required
                data-testid="input-end-chainage"
              />
            </div>
          </div>

          {road.carriageway === 'dual' && (
            <div>
              <Label className="block text-sm font-medium text-muted-foreground mb-2">Carriageway Side</Label>
              <Select value={formData.carriagewaySide} onValueChange={(value) => setFormData(prev => ({ ...prev, carriagewaySide: value }))}>
                <SelectTrigger className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all" data-testid="select-carriageway-side">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="lhs">Left Hand Side (LHS)</SelectItem>
                  <SelectItem value="rhs">Right Hand Side (RHS)</SelectItem>
                </SelectContent>
              </Select>
            </div>
          )}

          <div>
            <Label className="block text-sm font-medium text-muted-foreground mb-2">Completion Date</Label>
            <Input
              type="date"
              name="completionDate"
              value={formData.completionDate}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
              required
              data-testid="input-completion-date"
            />
          </div>

          <div>
            <Label className="block text-sm font-medium text-muted-foreground mb-2">Quality Status</Label>
            <Select value={formData.qualityStatus} onValueChange={(value) => setFormData(prev => ({ ...prev, qualityStatus: value }))}>
              <SelectTrigger className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all" data-testid="select-quality-status">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="approved">Approved</SelectItem>
                <SelectItem value="pending">Pending Review</SelectItem>
                <SelectItem value="rework">Requires Rework</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label className="block text-sm font-medium text-muted-foreground mb-2">Notes</Label>
            <Textarea
              name="notes"
              value={formData.notes}
              onChange={handleChange}
              rows={3}
              className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
              placeholder="Add any notes about this section"
              data-testid="textarea-progress-notes"
            />
          </div>

          <div className="flex justify-end space-x-4 pt-6 border-t border-border">
            <Button
              type="button"
              onClick={onClose}
              variant="outline"
              className="px-6 py-3 border border-border rounded-lg text-muted-foreground hover:bg-muted transition-colors"
              data-testid="button-cancel"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={mutation.isPending}
              className="px-6 py-3 bg-primary text-primary-foreground rounded-lg font-medium hover:bg-primary/90 transition-colors"
              data-testid="button-update-progress"
            >
              {mutation.isPending ? "Updating..." : "Update Progress"}
            </Button>
          </div>
          </div>
        </form>
      </div>
    </div>
  );
}

client/src/components/project-card.tsx.content:
import { Button } from "@/components/ui/button";
import SegmentedProgress from "@/components/segmented-progress";
import type { ProjectWithRoads } from "@shared/schema";

interface ProjectCardProps {
  project: ProjectWithRoads;
  onEdit: () => void;
  onDelete: () => void;
  onDuplicate: () => void;
  onAddRoad: () => void;
  onEditRoad: (road: any) => void;
  onAddProgress: (road: any, layerId: string) => void;
  onResetProgress: (layerId: string) => void;
}

export default function ProjectCard({
  project,
  onEdit,
  onDelete,
  onDuplicate,
  onAddRoad,
  onEditRoad,
  onAddProgress,
  onResetProgress,
}: ProjectCardProps) {
  // Calculate planned progress based on dates
  const calculatePlannedProgress = () => {
    if (!project.startDate || !project.endDate) return 0;

    const start = new Date(project.startDate);
    const end = new Date(project.endDate);
    const today = new Date();

    if (today < start) return 0;
    if (today > end) return 100;

    const totalDuration = end.getTime() - start.getTime();
    const elapsed = today.getTime() - start.getTime();
    return Math.min(100, Math.round((elapsed / totalDuration) * 100));
  };

  // Calculate actual progress based on layer completion
  const calculateActualProgress = () => {
    if (!project.roads || project.roads.length === 0) return 0;

    let totalProgress = 0;
    let totalWeight = 0;

    project.roads.forEach(road => {
      if (road.layers && road.layers.length > 0) {
        road.layers.forEach(layer => {
          const layerWeight = layer.weight || 1;
          totalWeight += layerWeight;

          if (layer.progress && layer.progress.length > 0) {
            const completedLength = layer.progress.reduce((sum, prog) => {
              return sum + (Number(prog.endChainage) - Number(prog.startChainage));
            }, 0);

            const layerProgress = (completedLength / Number(road.length)) * 100;
            totalProgress += layerProgress * layerWeight;
          }
        });
      }
    });

    return totalWeight > 0 ? Math.min(100, Math.round(totalProgress / totalWeight)) : 0;
  };

  const plannedProgress = calculatePlannedProgress();
  const actualProgress = calculateActualProgress();

  return (
    <div className="bg-card rounded-xl shadow-lg border border-border overflow-hidden card-hover" data-testid={`card-project-${project.id}`}>
      <div className="p-6">
        {/* Project Header */}
        <div className="flex justify-between items-start mb-4">
          <div>
            <h3 className="text-xl font-semibold text-card-foreground mb-1" data-testid="text-project-name">
              {project.name}
            </h3>
            <div className="flex items-center text-sm text-muted-foreground">
              <i className="fas fa-building mr-1"></i>
              <span data-testid="text-project-client">{project.client}</span>
            </div>
          </div>
          <div className="flex space-x-2">
            <button
              onClick={onEdit}
              className="text-muted-foreground hover:text-secondary transition-colors"
              title="Edit Project"
              data-testid="button-edit-project"
            >
              <i className="fas fa-edit"></i>
            </button>
            <button
              onClick={onDuplicate}
              className="text-muted-foreground hover:text-secondary transition-colors"
              title="Duplicate Project"
              data-testid="button-duplicate-project"
            >
              <i className="fas fa-copy"></i>
            </button>
            <button
              onClick={onDelete}
              className="text-muted-foreground hover:text-accent transition-colors"
              title="Delete Project"
              data-testid="button-delete-project"
            >
              <i className="fas fa-trash"></i>
            </button>
          </div>
        </div>

        {/* Project Details */}
        <div className="space-y-2 mb-6">
          <div className="flex items-center text-sm">
            <i className="fas fa-map-marker-alt w-4 text-muted-foreground mr-2"></i>
            <span className="text-muted-foreground">Location:</span>
            <span className="ml-1 text-card-foreground" data-testid="text-project-location">
              {project.location}
            </span>
          </div>
          <div className="flex items-center text-sm">
            <i className="fas fa-calendar w-4 text-muted-foreground mr-2"></i>
            <span className="text-muted-foreground">Duration:</span>
            <span className="ml-1 text-card-foreground" data-testid="text-project-duration">
              {project.startDate} to {project.endDate}
            </span>
          </div>
        </div>

        {/* Progress Indicators */}
        <div className="space-y-4 mb-6">
          <div>
            <div className="flex justify-between items-center mb-2">
              <span className="text-sm font-medium text-muted-foreground">Planned Progress</span>
              <span className="text-sm font-semibold text-secondary" data-testid="text-planned-progress">
                {plannedProgress}%
              </span>
            </div>
            <div className="w-full bg-muted rounded-full h-2">
              <div 
                className="bg-secondary h-2 rounded-full progress-bar-fill" 
                style={{ width: `${plannedProgress}%` }}
              ></div>
            </div>
          </div>

          <div>
            <div className="flex justify-between items-center mb-2">
              <span className="text-sm font-medium text-muted-foreground">Actual Progress</span>
              <span className="text-sm font-semibold text-green-600" data-testid="text-actual-progress">
                {actualProgress}%
              </span>
            </div>
            <div className="w-full bg-muted rounded-full h-2">
              <div 
                className="bg-green-500 h-2 rounded-full progress-bar-fill" 
                style={{ width: `${actualProgress}%` }}
              ></div>
            </div>
          </div>
        </div>

        {/* Roads Section */}
        <div className="border-t border-border pt-4">
          <div className="flex justify-between items-center mb-3">
            <h4 className="font-semibold text-card-foreground flex items-center">
              <i className="fas fa-road mr-2 text-muted-foreground"></i>
              Roads ({project.roads?.length || 0})
            </h4>
            <Button
              onClick={onAddRoad}
              variant="ghost"
              size="sm"
              className="text-xs bg-muted text-muted-foreground px-3 py-1 rounded-md hover:bg-secondary hover:text-secondary-foreground transition-colors"
              data-testid="button-add-road"
            >
              Add Road
            </Button>
          </div>

          {project.roads && project.roads.length > 0 ? (
            <div className="space-y-2" data-testid="roads-list">
              {project.roads.map((road) => (
                <div key={road.id} className="bg-muted/50 rounded-lg p-3" data-testid={`road-item-${road.id}`}>
                  <div className="flex justify-between items-center mb-2">
                    <span className="text-sm font-medium" data-testid="text-road-name">{road.name}</span>
                    <div className="flex space-x-1">
                      <button
                        onClick={() => onEditRoad(road)}
                        className="text-xs text-muted-foreground hover:text-secondary"
                        data-testid="button-edit-road"
                      >
                        <i className="fas fa-edit"></i>
                      </button>
                    </div>
                  </div>
                  <div className="space-y-1 text-xs">
                    {road.layers && road.layers.length > 0 ? (
                      road.layers.map((layer) => {
                        if (road.carriageway === 'dual') {
                          // Calculate LHS and RHS progress separately
                          const lhsProgress = layer.progress?.filter(p => p.carriagewaySide === 'lhs').reduce((sum, prog) => {
                            return sum + (Number(prog.endChainage) - Number(prog.startChainage));
                          }, 0) || 0;
                          const rhsProgress = layer.progress?.filter(p => p.carriagewaySide === 'rhs').reduce((sum, prog) => {
                            return sum + (Number(prog.endChainage) - Number(prog.startChainage));
                          }, 0) || 0;

                          const lhsPercentage = Math.round((lhsProgress / Number(road.length)) * 100);
                          const rhsPercentage = Math.round((rhsProgress / Number(road.length)) * 100);
                          const averagePercentage = Math.round((lhsPercentage + rhsPercentage) / 2);

                          return (
                            <div key={layer.id} className="space-y-2">
                              <div className="flex justify-between items-center">
                                <div className="flex items-center space-x-2">
                                  <span className="text-muted-foreground font-medium">{layer.name}</span>
                                  <span className={`font-semibold text-sm ${
                                    averagePercentage >= 100 ? 'text-green-600' : 
                                    averagePercentage >= 50 ? 'text-warning' : 'text-secondary'
                                  }`} data-testid="text-layer-average-progress">
                                    ({averagePercentage}%)
                                  </span>
                                </div>
                                <div className="flex items-center space-x-2">
                                  <button
                                    onClick={() => onResetProgress(layer.id)}
                                    className="text-xs text-muted-foreground hover:text-destructive"
                                    title="Reset Layer Progress"
                                    data-testid="button-reset-progress"
                                  >
                                    <i className="fas fa-undo"></i>
                                  </button>
                                  <button
                                    onClick={() => onAddProgress(road, layer.id)}
                                    className="text-xs text-muted-foreground hover:text-success"
                                    title="Add Progress"
                                    data-testid="button-add-progress"
                                  >
                                    <i className="fas fa-plus"></i>
                                  </button>
                                </div>
                              </div>
                              <div className="grid grid-cols-2 gap-4">
                                <div className="bg-background p-3 rounded border-l-2 border-blue-500">
                                  <div className="text-xs text-muted-foreground mb-2 font-medium">LHS</div>
                                  <div className="flex items-center justify-between mb-2">
                                    <span className={`font-medium text-xs ${
                                      lhsPercentage >= 100 ? 'text-green-600' : 
                                      lhsPercentage >= 50 ? 'text-warning' : 'text-secondary'
                                    }`} data-testid="text-layer-progress-lhs">
                                      {lhsPercentage}%
                                    </span>
                                  </div>
                                  <SegmentedProgress 
                                    progress={layer.progress || []}
                                    roadLength={Number(road.length)}
                                    carriagewaySide="lhs"
                                    layerId={layer.id}
                                  />
                                </div>
                                <div className="bg-background p-3 rounded border-l-2 border-orange-500">
                                  <div className="text-xs text-muted-foreground mb-2 font-medium">RHS</div>
                                  <div className="flex items-center justify-between mb-2">
                                    <span className={`font-medium text-xs ${
                                      rhsPercentage >= 100 ? 'text-green-600' : 
                                      rhsPercentage >= 50 ? 'text-warning' : 'text-secondary'
                                    }`} data-testid="text-layer-progress-rhs">
                                      {rhsPercentage}%
                                    </span>
                                  </div>
                                  <SegmentedProgress 
                                    progress={layer.progress || []}
                                    roadLength={Number(road.length)}
                                    carriagewaySide="rhs"
                                    layerId={layer.id}
                                  />
                                </div>
                              </div>
                            </div>
                          );
                        } else {
                          // Single carriageway - show combined progress
                          const completedLength = layer.progress?.reduce((sum, prog) => {
                            return sum + (Number(prog.endChainage) - Number(prog.startChainage));
                          }, 0) || 0;
                          const layerProgress = Math.round((completedLength / Number(road.length)) * 100);

                          return (
                            <div key={layer.id} className="space-y-2">
                              <div className="flex justify-between items-center">
                                <span className="text-muted-foreground font-medium">{layer.name}</span>
                                <div className="flex items-center space-x-2">
                                  <button
                                    onClick={() => onResetProgress(layer.id)}
                                    className="text-xs text-muted-foreground hover:text-destructive"
                                    title="Reset Layer Progress"
                                    data-testid="button-reset-progress"
                                  >
                                    <i className="fas fa-undo"></i>
                                  </button>
                                  <button
                                    onClick={() => onAddProgress(road, layer.id)}
                                    className="text-xs text-muted-foreground hover:text-success"
                                    title="Add Progress"
                                    data-testid="button-add-progress"
                                  >
                                    <i className="fas fa-plus"></i>
                                  </button>
                                </div>
                              </div>
                              <div className="space-y-2">
                                <div className="flex items-center justify-between">
                                  <span className={`font-medium text-xs ${
                                    layerProgress >= 100 ? 'text-green-600' : 
                                    layerProgress >= 50 ? 'text-warning' : 'text-secondary'
                                  }`} data-testid="text-layer-progress">
                                    {layerProgress}%
                                  </span>
                                </div>
                                <SegmentedProgress 
                                  progress={layer.progress || []}
                                  roadLength={Number(road.length)}
                                  carriagewaySide="both"
                                  layerId={layer.id}
                                />
                              </div>
                            </div>
                          );
                        }
                      })
                    ) : (
                      <div className="text-muted-foreground text-center py-2">No layers defined</div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-muted-foreground text-center py-4" data-testid="text-no-roads">
              No roads added yet
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

client/src/components/project-modal.tsx.content:
import { useState, useEffect } from "react";
import { useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { isUnauthorizedError } from "@/lib/authUtils";
import type { ProjectWithRoads, InsertProject } from "@shared/schema";

interface ProjectModalProps {
  project?: ProjectWithRoads | null;
  onClose: () => void;
  onSuccess: () => void;
}

export default function ProjectModal({ project, onClose, onSuccess }: ProjectModalProps) {
  const { toast } = useToast();
  const [formData, setFormData] = useState({
    name: "",
    client: "",
    location: "",
    startDate: "",
    endDate: "",
    description: "",
  });

  useEffect(() => {
    if (project) {
      setFormData({
        name: project.name || "",
        client: project.client || "",
        location: project.location || "",
        startDate: project.startDate || "",
        endDate: project.endDate || "",
        description: project.description || "",
      });
    }
  }, [project]);

  const mutation = useMutation({
    mutationFn: async (data: InsertProject) => {
      if (project) {
        await apiRequest("PATCH", `/api/projects/${project.id}`, data);
      } else {
        await apiRequest("POST", "/api/projects", data);
      }
    },
    onSuccess: () => {
      toast({
        title: "Success",
        description: `Project ${project ? "updated" : "created"} successfully`,
      });
      onSuccess();
    },
    onError: (error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Error",
        description: `Failed to ${project ? "update" : "create"} project`,
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    mutation.mutate(formData);
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }));
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="bg-card rounded-xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden">
        <div className="flex items-center justify-between p-6 border-b border-border">
          <h3 className="text-xl font-semibold text-card-foreground">
            {project ? "Edit Project" : "Add New Project"}
          </h3>
          <button
            onClick={onClose}
            className="text-muted-foreground hover:text-foreground transition-colors"
            data-testid="button-close-modal"
          >
            <i className="fas fa-times text-xl"></i>
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6 max-h-[calc(90vh-140px)] overflow-y-auto">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <Label className="block text-sm font-medium text-muted-foreground mb-2">Project Name</Label>
              <Input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
                placeholder="Enter project name"
                required
                data-testid="input-project-name"
              />
            </div>

            <div>
              <Label className="block text-sm font-medium text-muted-foreground mb-2">Client</Label>
              <Input
                type="text"
                name="client"
                value={formData.client}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
                placeholder="Enter client name"
                required
                data-testid="input-project-client"
              />
            </div>
          </div>

          <div>
            <Label className="block text-sm font-medium text-muted-foreground mb-2">Location</Label>
            <Input
              type="text"
              name="location"
              value={formData.location}
              onChange={handleChange}
              className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
              placeholder="Enter project location"
              required
              data-testid="input-project-location"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <Label className="block text-sm font-medium text-muted-foreground mb-2">Start Date</Label>
              <Input
                type="date"
                name="startDate"
                value={formData.startDate}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
                required
                data-testid="input-project-start-date"
              />
            </div>

            <div>
              <Label className="block text-sm font-medium text-muted-foreground mb-2">End Date</Label>
              <Input
                type="date"
                name="endDate"
                value={formData.endDate}
                onChange={handleChange}
                className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
                required
                data-testid="input-project-end-date"
              />
            </div>
          </div>

          <div>
            <Label className="block text-sm font-medium text-muted-foreground mb-2">Description</Label>
            <Textarea
              name="description"
              value={formData.description}
              onChange={handleChange}
              rows={4}
              className="w-full px-4 py-3 border border-input rounded-lg bg-background focus:ring-2 focus:ring-ring focus:border-transparent transition-all"
              placeholder="Enter project description"
              data-testid="textarea-project-description"
            />
          </div>

          <div className="flex justify-end space-x-4 pt-6 border-t border-border">
            <Button
              type="button"
              onClick={onClose}
              variant="outline"
              className="px-6 py-3 border border-border rounded-lg text-muted-foreground hover:bg-muted transition-colors"
              data-testid="button-cancel"
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={mutation.isPending}
              className="px-6 py-3 bg-secondary text-secondary-foreground rounded-lg font-medium hover:bg-secondary/90 transition-colors"
              data-testid="button-submit-project"
            >
              {mutation.isPending ? "Saving..." : project ? "Update Project" : "Create Project"}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

